import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        int n = Integer.parseInt(inputLine[0]);
        int mod = Integer.parseInt(inputLine[1]);

        long[] mem = new long[n + 1];
        Arrays.fill(mem, 0);
        mem[1] = 1;
        long total = 1;

        for (int i = 2; i <= n; i++) {
            int limit = (int) Math.sqrt(i) + 1;
            long current_sum = total;

            for (int f = 2; f < limit; f++) {
                current_sum = (current_sum + mem[i / f]) % mod;
            }

            int boundary = i;
            for (int j = 1; j <= i / limit; j++) {
                int next_val = i / (j + 1);
                current_sum = (current_sum + (boundary - next_val) * mem[j]) % mod;
                boundary = next_val;
            }

            total = (total + current_sum) % mod;
            mem[i] = current_sum;
        }

        System.out.println(mem[n]);
    }
}
